Object.assign(window.DYLEAN_DATA.files["Library/Init/Grind/Ordered/Int.lean"],{"text":"/-\nCopyright (c) 2025 Lean FRO, LLC. or its affiliates. All Rights Reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Kim Morrison\n-/\nmodule\n\nprelude\npublic import Init.Grind.Ordered.Ring\npublic import Init.GrindInstances.Ring.Int\nimport Init.Omega\n\npublic section\n\n/-!\n# `grind` instances for `Int` as an ordered module.\n-/\n\nopen Std\n\nnamespace Lean.Grind\n\ninstance : IsLinearOrder Int where\n  le_refl := Int.le_refl\n  le_trans _ _ _ := Int.le_trans\n  le_antisymm _ _ := Int.le_antisymm\n  le_total := Int.le_total\n\ninstance : LawfulOrderLT Int where\n  lt_iff := by omega\n\ninstance : OrderedAdd Int where\n  add_le_left_iff := by omega\n\ninstance : OrderedRing Int where\n  zero_lt_one := by omega\n  mul_lt_mul_of_pos_left := Int.mul_lt_mul_of_pos_left\n  mul_lt_mul_of_pos_right := Int.mul_lt_mul_of_pos_right\n\nend Lean.Grind\n","refs":[[22,0,22,8,"b1fcbb46ba93",true],[22,11,22,24,"7f22b0abd9a3",false],[22,25,22,28,"b00e7ff48cdd",false],[23,2,23,9,"545178b9bac8",false],[23,13,23,24,"5d4751399664",false],[24,2,24,10,"d27ea9d4ae76",false],[24,20,24,32,"adfedc62c522",false],[25,2,25,13,"cf4cb451b1e7",false],[25,21,25,36,"ded66d7ca050",false],[26,2,26,10,"7c65ab744fc7",false],[26,14,26,26,"1fdcd786a29a",false],[28,0,28,8,"8219cdb23175",true],[28,11,28,24,"113f9836a4a5",false],[28,25,28,28,"b00e7ff48cdd",false],[29,2,29,8,"e155803f836a",false],[31,0,31,8,"9ac9a0f8e2ff",true],[31,11,31,21,"8bf5384abebf",false],[31,22,31,25,"b00e7ff48cdd",false],[32,2,32,17,"f8e524cab654",false],[34,0,34,8,"af5498a531f8",true],[34,11,34,22,"54efb2039b77",false],[34,23,34,26,"b00e7ff48cdd",false],[35,2,35,13,"add217e0999e",false],[36,28,36,54,"66c1e08628cc",false],[37,29,37,56,"2c68fec18567",false]]});
